00054 // Parameters
00055 //
00056 //
00057 //
00058 class Parameters {
00059 public:
00060     static ParametersBuilder build();
00061     const ParameterRef operator[](const std::string &name) const;
00062 
00063 private:
00064     friend class ParametersBuilder;
00065     typedef std::map<std::string, std::shared_ptr<ParameterBase>> ParametersMap;
00066 
00067     Parameters(const ParametersMap &parameters);
00068 
00069     const ParametersMap parameters_;
00070 };
00071 
00072 // Parameters Builder
00073 //
00074 class ParametersBuilder {
00075 public:
00076     ParametersBuilder &set_json(const std::string &str);
00077     template <typename T> ParametersBuilder &set(const std::string &name, const T &value);
00078     Parameters finish();
00079 
00080 private:
00081     Parameters::ParametersMap parameters_;
00082 };
00083 
00084 // All parameter types derive from this
00085 //
00086 class ParameterBase {
00087 public:
00088     ParameterBase(const std::string &name) : name_(name) {}
00089     virtual ~ParameterBase() = 0;
00090 
00091 protected:
00092     friend ParameterRef;
00093     const std::string name_;
00094 };
00095 
00096 // Per type template derived from ParameterBase
00097 //
00098 template <typename T> class Parameter : public ParameterBase {
00099 public:
00100     Parameter(const std::string &name, const T &value) : ParameterBase(name), value_(value) {}
00101 
00102 private:
00103     friend ParameterRef;
00104     T value_;
00105 };
00106 
00107 template <typename T> ParametersBuilder &ParametersBuilder::set(const std::string &name, const T &value) {
00108     Parameters::ParametersMap::iterator i = parameters_.find(name);
00109     if (i == parameters_.end())
00110         parameters_.insert(Parameters::ParametersMap::value_type(name, new Parameter<T>(name, value)));
00111     else {
00112         i->second = std::shared_ptr<ParameterBase>(new Parameter<T>(name, value));
00113     }
00114     return *this;
00115 }
00116 
00117 // Adapter type returned by Paramters::operator[] - wraps a ParamterBase pointer.
00118 //
00119 class ParameterRef {
00120 public:
00121     ParameterRef(const std::string &name, const ParameterBase *base) : name_(name), base_(base) {}
00122 
00123     // Does parameter exist?
00124     bool empty() const { return base_ == nullptr; }
00125 
00126     // Is parameter of a particular type?
00127     template <typename T> bool is() const {
00128         if (!base_)
00129             return false;
00130 
00131         const Parameter<T> *p = dynamic_cast<const Parameter<T> *>(base_);
00132         return p != nullptr;
00133     }
00134 
00135     // Get value as a particular type
00136     template <typename T> T get(T dflt = T()) const {
00137         if (!base_)
00138             return dflt;
00139 
00140         const Parameter<T> *p = dynamic_cast<const Parameter<T> *>(base_);
00141         if (p) {
00142             return p->value_;
00143         } else {
00144             ERR("Parameter type mismatch: %s", name_.c_str());
00145             return dflt;
00146         }
00147     }
00148 
00149     // Get value as a particular type
00150     template <typename T> T get(const Parameters &defaults) const {
00151         if (!base_)
00152             return defaults[name_].get<T>();
00153 
00154         const Parameter<T> *p = dynamic_cast<const Parameter<T> *>(base_);
00155         if (p) {
00156             return p->value_;
00157         } else {
00158             ERR("Parameter type mismatch: %s", name_.c_str());
00159             return defaults[name_].get<T>();
00160         }
00161     }
00162 
00163     // Get a string value as an enum
00164     // Expects 'std::istream & operator >> (std::istream &in, T &v)' to exist via extract<T>()
00165     //
00166     template <typename T> T get_enum(T dflt) const {
00167         if (!base_)
00168             return dflt;
00169 
00170         const Parameter<std::string> *p = dynamic_cast<const Parameter<std::string> *>(base_);
00171         if (p) {
00172             return extract<T>(p->value_, dflt);
00173         } else {
00174             ERR("Parameter type mismatch: %s", name_.c_str());
00175             return dflt;
00176         }
00177     }
00178 
00179     template <typename T> T get_enum(const Parameters &defaults) const {
00180         T dflt = defaults[name_].get_enum<T>(static_cast<T>(0));
00181         if (!base_)
00182             return dflt;
00183 
00184         const Parameter<std::string> *p = dynamic_cast<const Parameter<std::string> *>(base_);
00185         if (p) {
00186             return extract<T>(p->value_, dflt);
00187         } else {
00188             ERR("Parameter type mismatch: %s", name_.c_str());
00189             return dflt;
00190         }
00191     }
00192 
00193     // Get a string value as a vector
00194     // Expects 'std::istream & operator >> (std::istream &in, T &v)' to exist via extract<T>()
00195 
00196     template <typename T> T *get_vector(T *dest, unsigned size) const {
00197         if (!base_)
00198             return dest;
00199 
00200         const Parameter<std::string> *p = dynamic_cast<const Parameter<std::string> *>(base_);
00201         if (p) {
00202             std::istringstream ss(p->value_);
00203             T r;
00204             for (unsigned i = 0; i < size; i++) {
00205                 ss >> r;
00206                 dest[i] = r;
00207             }
00208             return dest;
00209         } else {
00210             ERR("Parameter type mismatch: %s", name_.c_str());
00211             return dest;
00212         }
00213     }
00214 
00215 private:
00216     const std::string name_;
00217     const ParameterBase *const base_;
00218 };
00219 
00220 // Specialization for converting double->unsigned and double->int
00221 //
00222 // A bit sketchy - shuould really have some sort of schema
00223 //
00224 template <> inline unsigned ParameterRef::get(unsigned dflt) const {
00225     if (is<unsigned>()) {
00226         // fix assignment
00227         const Parameter<unsigned> *p = dynamic_cast<const Parameter<unsigned> *>(base_);
00228         return (unsigned)(p->value_);
00229     }
00230 
00231     if (is<int>()) {
00232         // fix assignment
00233         const Parameter<int> *p = dynamic_cast<const Parameter<int> *>(base_);
00234         return (unsigned)(p->value_);
00235     }
00236 
00237     if (is<double>()) {
00238         // fix assignment
00239         const Parameter<double> *p = dynamic_cast<const Parameter<double> *>(base_);
00240         return (unsigned)(double)(p->value_);
00241     }
00242 
00243     return dflt;
00244 }
00245 
00246 template <> inline int ParameterRef::get(int dflt) const {
00247     if (is<int>())
00248         return get<int>(dflt);
00249 
00250     if (is<unsigned>())
00251         return get<unsigned>(dflt);
00252 
00253     if (is<double>())
00254         return (int)get<double>(dflt);
00255 
00256     return dflt;
00257 }
00258 
00259 template <> inline unsigned ParameterRef::get<unsigned>(const Parameters &defaults) const {
00260     if (!base_)
00261         return defaults[name_].get<unsigned>();
00262 
00263     if (is<unsigned>()) {
00264         // fix assignment
00265         const Parameter<unsigned> *p = dynamic_cast<const Parameter<unsigned> *>(base_);
00266         return (unsigned)(p->value_);
00267     }
00268 
00269     if (is<int>()) {
00270         // fix assignment
00271         const Parameter<int> *p = dynamic_cast<const Parameter<int> *>(base_);
00272         return (unsigned)(p->value_);
00273     }
00274 
00275     if (is<double>()) {
00276         // fix assignment
00277         const Parameter<double> *p = dynamic_cast<const Parameter<double> *>(base_);
00278         return (unsigned)(double)(p->value_);
00279     }
00280 
00281     return defaults[name_].get<unsigned>();
00282 }
00283 
00284 template <> inline int ParameterRef::get<int>(const Parameters &defaults) const {
00285     if (!base_)
00286         return defaults[name_].get<int>();
00287 
00288     if (is<unsigned>())
00289         return get<unsigned>(0);
00290 
00291     if (is<int>())
00292         return get<int>(0);
00293 
00294     if (is<double>())
00295         return (int)get<double>(0);
00296 
00297     return defaults[name_].get<int>();
00298 }
